public class TimeRangeBuilder {
    private static final long FETCH_DATA_DURATION = 1000; // Example duration in milliseconds

    /**
     * Split time ranges to insure the start time and end time is small then {@link #FETCH_DATA_DURATION}
     *
     * @param start The start time of the range
     * @param end   The end time of the range
     * @return A list of time ranges
     */
    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = start;

        while (currentEnd <= end) {
            if (currentEnd - currentStart > FETCH_DATA_DURATION) {
                timeRanges.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
                currentStart = currentStart + FETCH_DATA_DURATION;
            } else {
                timeRanges.add(new TimeRange(currentStart, currentEnd));
                break;
            }
            currentEnd = currentEnd + FETCH_DATA_DURATION;
        }

        return timeRanges;
    }

    // Example TimeRange class
    public static class TimeRange {
        private long start;
        private long end;

        public TimeRange(long start, long end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public String toString() {
            return "TimeRange{" +
                    "start=" + start +
                    ", end=" + end +
                    '}';
        }
    }
}

