public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int b = str.charAt(i);
        if ((b & 0x80) == 0) {
            size++;
        } else if ((b & 0xE0) == 0xC0) {
            size += 2;
        } else if ((b & 0xF0) == 0xE0) {
            size += 3;
        } else if ((b & 0xF8) == 0xF0) {
            size += 4;
        }
    }
    return size;
}

