import java.net.URI;
import java.util.ArrayList;
import java.util.List;

public class URIUtils {
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        String[] segments = path.split("/");
        for (String segment : segments) {
            if (decode) {
                segment = decodeURIComponent(segment);
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

    private static String decodeURIComponent(String segment) {
        StringBuilder decoded = new StringBuilder();
        for (int i = 0; i < segment.length(); i++) {
            char c = segment.charAt(i);
            if (c == '%') {
                if (i + 2 < segment.length()) {
                    String hex = segment.substring(i + 1, i + 3);
                    decoded.append((char) Integer.parseInt(hex, 16));
                    i += 2;
                } else {
                    throw new IllegalArgumentException("Invalid URI segment: " + segment);
                }
            } else {
                decoded.append(c);
            }
        }
        return decoded.toString();
    }
}

