public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double halfWidth = box.getWidth() / 2;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(box.getMinX() + halfWidth, box.getMinY(), box.getWidth() - halfWidth, box.getHeight());
    return Pair.with(leftBox, rightBox);
}

