public final class ClassFileReader {
    private final byte[] classFileBuffer;

    public ClassFileReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    /**
     * Reads a CONSTANT_Utf8 constant pool entry in {@link #classFileBuffer}.
     * @param constantPoolEntryIndex the index of a CONSTANT_Utf8 entry in the class's constant pool table.
     * @param charBuffer the buffer to be used to read the string. This buffer must be sufficientlylarge. It is not automatically resized.
     * @return the String corresponding to the specified CONSTANT_Utf8 entry.
     */
    public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        int utf8Length = classFileBuffer[constantPoolEntryIndex + 1];
        int utf8Offset = constantPoolEntryIndex + 2;
        for (int i = 0; i < utf8Length; i++) {
            charBuffer[i] = (char) (classFileBuffer[utf8Offset + i] & 0xFF);
        }
        return new String(charBuffer, StandardCharsets.UTF_8);
    }
}

