    public ByteVector putInt(final int intValue) {
        int byteSize = 4; // Size of an int in bytes
        byte[] intBytes = new byte[byteSize];
        intBytes[0] = (byte) (intValue >> 24);
        intBytes[1] = (byte) (intValue >> 16);
        intBytes[2] = (byte) (intValue >> 8);
