public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid name start index");
    }

    int end = nameStart;
    while (end < buf.length() && Character.isLetter(buf.charAt(end))) {
        end++;
    }

    if (end - nameStart > 3) {
        buf.append(buf.substring(nameStart, end - 3));
        buf.append("...");
    } else {
        buf.append(buf.substring(nameStart, end));
    }
}

